function lessonQuestionRecord(lessonId,q,index){const id=`${lessonId}-lesson-q${String(index+1).padStart(2,'0')}`;return {id,revision:1,lessonId,type:'choice',conceptTags:['lesson-check'],prompt:q.q,options:q.options.map((text,i)=>({id:`${id}-o${i+1}`,text})),correctOptionId:`${id}-o${q.answer+1}`,feedback:q.options.map((_,i)=>q.feedback[i]||'선택한 답을 본문의 설명과 비교해 보세요.'),reviewTargets:[{lessonId,sectionId:q.review}]};}
