function route(){const raw=location.hash.replace(/^#/,'')||'overview',[path,query='']=raw.split('?'),parts=path.split('/'),params=new URLSearchParams(query),id=parts[0];if(id==='exams'){renderExams();}else if(id==='exam'&&parts[1]==='setup'){renderExamSetup(parts[2]);}else if(id==='exam'&&parts[1]==='run'){renderExamRun(parts[2]);}else if(id==='exam'&&parts[1]==='result'){renderExamResult(parts[2]);}else if(id==='review'){renderReview(parts[1]);}else if(id==='cases'){renderCases();}else if(id==='case'){renderCase(parts[1],parts[2]||'observe',params.get('lab')||'');}else{const section=parts[1],returnId=params.get('return')||'',caseReturn=params.get('caseReturn')||'';if(id!==currentId||(returnId||caseReturn)!==lessonReturnId){if(id==='overview')renderOverview();else if(id==='glossary')renderGlossary();else renderLesson(id,returnId,caseReturn);}if(section){document.getElementById(section)?.scrollIntoView({block:'start'});}else{window.scrollTo(0,0);main.querySelector('h1')?.focus({preventScroll:true});}}document.body.classList.remove('menu-open');menu.setAttribute('aria-expanded','false');menu.textContent='목차 열기';}
menu.addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'목차 닫기':'목차 열기';if(open)sidebar.querySelector('[aria-current=page]')?.focus();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('menu-open')){document.body.classList.remove('menu-open');menu.setAttribute('aria-expanded','false');menu.textContent='목차 열기';menu.focus();}});
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();main.focus();window.scrollTo(0,0);});
window.addEventListener('hashchange',route);window.addEventListener('storage',event=>{if(event.key==='cs-course:assessment:v1'&&location.hash.includes('#exam/run/'))route();});window.addEventListener('pagehide',()=>{cleanup.forEach(fn=>fn());CS.assessment.storage.release();});window.addEventListener('pageshow',event=>{if(event.persisted)route();});route();
